function divideNumbers(a, b) {
  try {
    if (typeof a !== 'number' || typeof b !== 'number') {
      // Creating and throwing a custom error
      throw new TypeError("Both arguments must be numbers!");
    }
    if (b === 0) {
      throw new Error("Cannot divide by zero!");
    }

    console.log(`Result: ${a / b}`);
    return true;

  } catch (error) {
    // This block only runs if an error was thrown
    console.error("Uh oh! Something went wrong.");
    console.error(`Error Type: ${error.name}`);
    console.error(`Message: ${error.message}`);
    return false;

  } finally {
    // This block ALWAYS runs, error or no error
    console.log("Cleanup: Division operation finished.\n");
  }
}

divideNumbers(10, 2);  // Succeeds
divideNumbers(10, 0);  // Throws Error
divideNumbers("10", 2); // Throws TypeError
